 * 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or more points.
 */
default int membershipLevel(Owner owner) {
    int points = membershipPoints(owner);
    if (points <= 1) {
        return 1;
    }
    if (points <= 3) {
        return 2;
    }
    if (points <= 5) {
        return 3;
    }
